//! Actual private signed admission/authority/store; no provider quota or host profile.
use super::{admission::{self,Review as AdmissionReview},admission_tests::{Fixture,evidence,budget},authority::Authority,authority_store::Fault,authority_tests::root,model::{self,Record,Action},retirement_controller::{Prepared,Review},store::{Store,nonce},reconciliation_tests::inventory};
use std::{fs,os::{fd::AsRawFd,unix::fs::PermissionsExt},fs::OpenOptions};
fn native(f:&Fixture)->Store{Store::existing_verified(&f.path.join("goals"),&root(f)).unwrap().unwrap()}
pub(super)fn initial(provider:&str,planning:bool)->(Fixture,Store,Record,String){
    let f=Fixture::new();let goal=f.goal(provider);let authority=Authority::ensure(&root(&f)).unwrap();let prepared=if planning{
        let mut bounds=budget();bounds.payment=admission::Payment::LocalOnly;let mut config=crate::pet_config::defaults();config.pets.get_mut("ai_ollama").unwrap().permissions.get_or_insert_default().music=true;
        AdmissionReview::prepare_planning(&goal,evidence(&goal,100_002),bounds,super::planning::Limits{max_rounds:3,max_steps:2,max_output_bytes:2048,no_progress_limit:2},&config,"issued-only".into(),nonce().unwrap(),100_002).unwrap()
    }else{AdmissionReview::prepare(&goal,evidence(&goal,100_002),budget(),"issued-only".into(),nonce().unwrap(),100_002).unwrap()};
    let approved=prepared.approve(&goal,evidence(&goal,100_003),100_003).unwrap();let decision=approved.spec().decision_id.clone();authority.certify(&approved,&goal,100_004).unwrap();let store=native(&f);(f,store,goal,decision)
}
pub(super)fn review(f:&Fixture,store:&Store,goal:&Record,decision:&str,at:u64)->Review{
    match store.prepare_retirement(&root(f),&goal.id,&goal.spec.owner.pet_id,&goal.revision,decision,"retire-unused".into(),at).unwrap(){Prepared::Review(review)=>review,Prepared::Retired(_)=>panic!("a new native review is required")}
}
fn grant(f:&Fixture,decision:&str)->serde_json::Value{serde_json::from_slice(&fs::read(root(f).join(format!("{decision}.json"))).unwrap()).unwrap()}
#[test]fn all_native_pets_retire_unused_authority_without_reconstructing_an_admission_or_consumption(){
    for(provider,planning)in[("codex",false),("copilot",false),("antigravity",false),("ollama",false),("ollama",true)]{
        let(f,store,g,decision)=initial(provider,planning);let before=inventory(&f.path);let old=grant(&f,&decision);let prepared=review(&f,&store,&g,&decision,100_040);let p=prepared.proposal();assert_eq!(inventory(&f.path),before);assert!(!p.execution_available&&p.target_usage_known_zero&&!p.history_continuity_verified);assert_eq!(p.authenticated_subtotal.model_calls,0);assert_eq!(p.authenticated_subtotal.tool_calls,0);assert_eq!(p.original_approved_at,100_003);
        let choice=prepared.decide(100_041).unwrap();let mut approved=prepared.approve(choice);let receipt=approved.confirm(&store,100_042).unwrap();assert_eq!(receipt.status,model::CommitStatus::Durable);assert_eq!(model::fingerprint(&receipt.record).unwrap(),model::fingerprint(&g).unwrap());assert!(!receipt.execution_available&&!receipt.new_admission_created);
        let current=grant(&f,&decision);assert_eq!(current["body"]["schemaVersion"],8);assert_eq!(current["body"]["phase"],"revoked");assert_eq!(current["body"]["specHash"],old["body"]["specHash"]);assert_eq!(current["body"]["approvedAt"],old["body"]["approvedAt"]);assert!(current["body"].get("lease").is_none());assert!(current["body"].get("runtimeOwner").is_none());assert_eq!(receipt.reference.source_grant_schema,if planning{4}else{1});
        let changed=inventory(&f.path).into_iter().filter(|(name,hash)|before.get(name)!=Some(hash)).collect::<Vec<_>>();assert_eq!(changed.len(),1);assert_eq!(store.read(&g.id,&g.spec.owner.pet_id).unwrap().admissions.len(),0);let history=store.history(&root(&f),&g.id,&g.spec.owner.pet_id,&g.revision,100_043).unwrap();assert!(history.accounting_complete);assert_eq!(history.cumulative_charge.unwrap().model_calls,0);assert!(history.unlinked_grants[0].revoked_without_io);
        let stable=inventory(&f.path);let ack=approved.acknowledged();ack.receipt(&store).unwrap();assert_eq!(inventory(&f.path),stable);
    }
}
#[test]fn retirement_of_an_orphaned_continuation_preserves_the_original_unknown_model_charge(){
    let(env,g)=super::continuation_tests::closed("ollama","started");let original=env.grant();let mut approved=super::continuation_tests::review(&env,&g,"lost-before-goal-write",100_030).approve(&g,evidence(&g,100_031),100_031).unwrap();let decision=approved.spec().decision_id.clone();let authority=approved.take_native_authority().unwrap();authority.certify(&approved,&g,100_032).unwrap();drop(approved);let prepared=review(&env.fixture,&env.store,&g,&decision,100_040);assert_eq!(prepared.proposal().authenticated_subtotal.model_calls,1);assert_eq!(prepared.proposal().authenticated_subtotal.unknown_model_results,1);
    let choice=prepared.decide(100_041).unwrap();let mut approved=prepared.approve(choice);approved.confirm(&env.store,100_042).unwrap();assert_eq!(env.grant(),original);let before=inventory(&env.fixture.path);let next=super::continuation_tests::review(&env,&g,"new-after-retirement",100_043).proposal();let history=next.continuation.unwrap();assert_eq!(history.charge.model_calls,1);assert_eq!(history.charge.unknown_model_results,1);assert_eq!(history.unused.len(),1);assert_eq!(history.unused[0].decision_id,decision);assert_eq!(inventory(&env.fixture.path),before);
}
#[test]fn busy_and_partial_revocation_keep_one_original_choice_and_retire_only_its_native_temporaries(){
    for fault in[Fault::BeforeGrantPublish,Fault::AfterGrantPublish]{
        let(f,store,g,decision)=initial("ollama",false);let prepared=review(&f,&store,&g,&decision,100_040);let choice=prepared.decide(100_041).unwrap();let mut approved=prepared.approve(choice);let reference=approved.reference.clone();let lock=OpenOptions::new().read(true).write(true).open(root(&f).join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_SH|libc::LOCK_NB)},0);let before=inventory(&f.path);
        assert_eq!(approved.confirm(&store,100_042).err(),Some(model::Error::Busy));assert!(!approved.write_started);assert_eq!(inventory(&f.path),before);drop(lock);approved.authority.fault=fault;assert!(approved.confirm(&store,100_043).is_err());assert!(approved.write_started);approved.authority.fault=Fault::None;
        let receipt=approved.confirm(&store,300_000).unwrap();assert_eq!(receipt.reference,reference);assert_eq!(receipt.reference.approved_at,100_041);assert_eq!(grant(&f,&decision)["body"]["approvedAt"],100_003);assert!(!fs::read_dir(root(&f)).unwrap().any(|p|p.unwrap().file_name().to_string_lossy().starts_with(".grant-")));let stable=inventory(&f.path);approved.confirm(&store,300_001).unwrap();assert_eq!(inventory(&f.path),stable);
    }
}
#[test]fn a_recorded_retirement_is_acknowledged_after_cache_loss_and_later_cancel_without_overwriting_the_goal(){
    let(f,store,g,decision)=initial("codex",false);let prepared=review(&f,&store,&g,&decision,100_040);let choice=prepared.decide(100_041).unwrap();let mut approved=prepared.approve(choice);approved.authority.fault=Fault::AfterGrantPublish;assert!(approved.confirm(&store,100_042).is_err());drop(approved);
    let cancelled=store.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"later-cancel".into(),Action::Cancel,100_043).unwrap().record;let before=inventory(&f.path);
    let receipt=match store.prepare_retirement(&root(&f),&g.id,&g.spec.owner.pet_id,&cancelled.revision,&decision,"ack-after-restart".into(),400_000).unwrap(){Prepared::Retired(receipt)=>receipt,Prepared::Review(_)=>panic!("recorded retirement must not be reauthorized")};assert_eq!(receipt.record.state,model::State::Cancelled);assert_eq!(receipt.record.revision,cancelled.revision);assert_eq!(receipt.reference.approved_at,100_041);assert_eq!(inventory(&f.path),before);
}
#[test]fn declining_a_staged_uncommitted_retirement_preserves_the_original_unused_signed_grant(){
    let(f,store,g,decision)=initial("ollama",false);let original=grant(&f,&decision);let prepared=review(&f,&store,&g,&decision,100_040);let choice=prepared.decide(100_041).unwrap();let mut approved=prepared.approve(choice);approved.authority.fault=Fault::BeforeGrantPublish;assert!(approved.confirm(&store,100_042).is_err());approved.authority.fault=Fault::None;assert!(store.withdraw_retirement(&approved).unwrap());assert_eq!(grant(&f,&decision),original);assert!(!fs::read_dir(root(&f)).unwrap().any(|p|p.unwrap().file_name().to_string_lossy().starts_with(".grant-")));let _=review(&f,&store,&g,&decision,100_043);
}
#[test]fn changed_goal_or_replaced_canonical_inode_rejects_the_old_review_without_retirement(){
    for change in["goal","inode"]{
        let(f,store,g,decision)=initial("codex",false);let prepared=review(&f,&store,&g,&decision,100_040);
        if change=="goal"{store.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"cancel-before-choice".into(),Action::Cancel,100_041).unwrap();let choice=prepared.decide(100_042).unwrap();let mut approved=prepared.approve(choice);let before=inventory(&f.path);assert!(approved.confirm(&store,100_043).is_err());assert_eq!(inventory(&f.path),before);assert!(!approved.write_started);}else{let path=root(&f).join(format!("{decision}.json"));let bytes=fs::read(&path).unwrap();fs::remove_file(&path).unwrap();fs::write(&path,&bytes).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o600)).unwrap();let before=inventory(&f.path);assert!(prepared.decide(100_041).is_err());assert_eq!(inventory(&f.path),before);}
    }
}
#[test]fn staged_only_linked_claimed_foreign_or_corrupt_sources_do_not_create_retirement_authority(){
    let(f,store,g,decision)=initial("codex",false);fs::rename(root(&f).join(format!("{decision}.json")),root(&f).join(format!(".grant-{}",nonce().unwrap()))).unwrap();let before=inventory(&f.path);assert!(store.prepare_retirement(&root(&f),&g.id,&g.spec.owner.pet_id,&g.revision,&decision,"stage-only".into(),100_040).is_err());assert_eq!(inventory(&f.path),before);
    let env=super::recovery_tests::Environment::new("ollama","started",true);let row=&env.goal.admissions[0];let before=inventory(&env.fixture.path);assert!(env.store.prepare_retirement(&root(&env.fixture),&env.goal.id,"ai_ollama",&env.goal.revision,&row.spec.decision_id,"linked".into(),100_040).is_err());assert_eq!(inventory(&env.fixture.path),before);
    let forged=Record::new(env.goal.spec.clone(),env.goal.created_at,nonce().unwrap()).unwrap();fs::write(env.fixture.path.join("goals").join(format!("{}.json",forged.id)),serde_json::to_vec(&forged).unwrap()).unwrap();let before=inventory(&env.fixture.path);assert!(env.store.prepare_retirement(&root(&env.fixture),&forged.id,"ai_ollama",&forged.revision,&row.spec.decision_id,"omitted-claimed".into(),100_041).is_err());assert_eq!(inventory(&env.fixture.path),before);
    let(f,store,g,decision)=initial("codex",false);let other=Fixture::new();Authority::ensure(&root(&other)).unwrap();let before=inventory(&f.path);assert!(store.prepare_retirement(&root(&other),&g.id,&g.spec.owner.pet_id,&g.revision,&decision,"foreign".into(),100_040).is_err());assert_eq!(inventory(&f.path),before);
    let path=root(&f).join(format!("{decision}.json"));let mut body=grant(&f,&decision);body["tag"]=serde_json::json!("a".repeat(64));fs::write(&path,serde_json::to_vec(&body).unwrap()).unwrap();let before=inventory(&f.path);assert!(store.prepare_retirement(&root(&f),&g.id,&g.spec.owner.pet_id,&g.revision,&decision,"corrupt".into(),100_040).is_err());assert_eq!(inventory(&f.path),before);
}
#[test]fn result_directories_and_untrusted_foreign_tool_identities_cannot_prove_no_io(){
    for artifact in["result","planning","step"]{
        let(f,store,g,decision)=initial("ollama",false);let authority=Authority::existing(&root(&f)).unwrap();
        if artifact=="step"{let dir=super::store::protocol_directory(&f.path.join("pet-runtime-step-consent-v1"),b"{\"version\":1,\"kind\":\"coucou-native-goal-steps\"}\n",true).unwrap().unwrap();dir.write_new(&format!("{}.json","a".repeat(64)),&serde_json::to_vec(&serde_json::json!({"body":{"scope":{"decisionId":nonce().unwrap()}},"tag":"forged"})).unwrap()).unwrap();}
        else{let(path,protocol)=if artifact=="result"{(authority.result_root().unwrap(),b"{\"version\":1,\"kind\":\"coucou-model-results\"}\n".as_slice())}else{(authority.planning_root().unwrap(),b"{\"version\":1,\"kind\":\"coucou-native-planning-output\"}\n".as_slice())};super::store::protocol_directory(&path,protocol,true).unwrap();super::store::protocol_directory(&path.join(&decision),protocol,true).unwrap();}
        let before=inventory(&f.path);assert!(store.prepare_retirement(&root(&f),&g.id,&g.spec.owner.pet_id,&g.revision,&decision,"contradiction".into(),100_040).is_err());assert_eq!(inventory(&f.path),before);
    }
}
#[test]fn authentic_foreign_steps_recipes_evidence_and_verification_do_not_block_another_goals_unused_grant(){
    use std::sync::Arc;use crate::spotify::goal::{Target,tests::{Bus,Player}};
    let(f,authority,goal,_pending,owner,_main)=super::generated_effect_tests::setup(true);let bus=Bus::new();let _player=Player::new(&bus,"Private foreign retirement fixture");let config=super::generated_effect_tests::config();let now=crate::assistant_memory::now();let reviewed=owner.review_recipe_with_criteria(&goal,&goal.plans[0].id,"foreign-approved",Arc::new(Target::fixture_at(&bus.address).unwrap()),&config,&[],now).unwrap();let(approved,ready)=reviewed.approve(&owner,&goal,&config,now).unwrap();let scope=authority.issue_recipe(&goal.admissions[0].spec,goal.admissions[0].proof.as_ref().unwrap(),owner.lease(),&approved,now).unwrap();ready.activate(&scope).unwrap();let store=native(&f);assert!(owner.run_recipe_for_store(&store,&goal,&ready,||Ok(config.clone()),|_|{}).unwrap().progress.goal_complete);
    let draft=f.goal_named_criteria("ollama","separate-unused",vec!["Separate original goal".into()]);let mut bounds=budget();bounds.deadline_at=now+120_000;let review=AdmissionReview::prepare(&draft,evidence(&draft,now),bounds,"separate-unused-admit".into(),nonce().unwrap(),now).unwrap();let approved=review.approve(&draft,evidence(&draft,now+1),now+1).unwrap();let decision=approved.spec().decision_id.clone();authority.certify(&approved,&draft,now+2).unwrap();let prepared=match store.prepare_retirement(&root(&f),&draft.id,"ai_ollama",&draft.revision,&decision,"retire-separate".into(),now+3).unwrap(){Prepared::Review(review)=>review,_=>panic!("new separate review required")};let choice=prepared.decide(now+4).unwrap();let mut approved=prepared.approve(choice);approved.confirm(&store,now+5).unwrap();assert_eq!(store.read(&goal.id,"ai_ollama").unwrap().state,model::State::Completed);
}
